using System.IO;

using Shouldly;
using Xunit;

using Assimalign.Cohesion.Content.Binary;
using Assimalign.Cohesion.Content.Bmff;

namespace Assimalign.Cohesion.Content.Mpeg.Tests;

public sealed class Mp4InspectionTraversalTests
{
    [Fact(DisplayName = "Cohesion Test [Content.Mpeg] - Inspection: generic traversal reaches sample entries and lazy configuration")]
    public void Walk_ProgressiveProfile_VisitsTypedProfileBoxes()
    {
        // Arrange: the progressive fixture is generated by this repository's BMFF writer.
        using var source = new MemoryStream(Mp4GoldenFixtures.Create("progressive.mp4"));
        using var document = Mp4Profile.LoadDocument(source);
        var count = 0;

        // Act
        BmffBoxWalker.Walk(document, (box, depth, path) =>
        {
            if (box is AvcConfigurationBox) { count++; path[^1].ShouldBe(FourCC.Parse("avcC")); }
            return BmffWalkAction.Continue;
        });
        var entry = document.First<Avc1SampleEntryBox>();

        // Assert
        count.ShouldBe(1);
        entry.Children<AvcConfigurationBox>().ShouldHaveSingleItem();
        document.First(FourCC.Parse("avc1")).ShouldBeSameAs(entry);
        entry.IsComposite.ShouldBeTrue();
        document.First<AvcConfigurationBox>().IsLeaf.ShouldBeTrue();
    }
}
